import { spawn } from "node:child_process";

// The CLI accepts a 1 MiB Node response and prints its compact JSON plus a newline.
// Leave room for re-encoding, and for local git probes before the 5s POST and 40s wait.
const MAX_STDOUT_BYTES = 2 * 1024 * 1024;
const HOOK_LIFETIME_MS = 90_000;

function runHook(
  command: readonly string[] | null,
  payload: object,
  answered?: (value: unknown) => unknown,
) {
  if (!command?.[0]) return;
  const input = JSON.stringify(payload);
  const child = spawn(command[0], command.slice(1), { stdio: ["pipe", "pipe", "ignore"] });
  const chunks: Buffer[] = [];
  let bytes = 0;
  let stopped = false;
  const timer = setTimeout(cancel, HOOK_LIFETIME_MS);
  timer.unref();

  function cancel() {
    if (stopped) return;
    stopped = true;
    clearTimeout(timer);
    chunks.length = 0;
    child.stdin.destroy();
    child.stdout.destroy();
    if (child.exitCode === null && child.signalCode === null) child.kill("SIGKILL");
  }

  child.on("error", cancel);
  child.stdin.on("error", cancel);
  child.stdout.on("error", cancel);
  child.stdout.on("data", (chunk: Buffer) => {
    if (stopped) return;
    bytes += chunk.length;
    if (bytes > MAX_STDOUT_BYTES) cancel();
    else if (answered) chunks.push(chunk);
  });
  child.once("close", (code) => {
    clearTimeout(timer);
    if (stopped || code !== 0 || !answered || bytes === 0) return;
    try {
      // Keep a leading BOM in the text so JSON.parse enforces the original JSON grammar.
      const decoder = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });
      const value: unknown = JSON.parse(decoder.decode(Buffer.concat(chunks, bytes)));
      Promise.resolve(answered(value)).catch(() => {});
    } catch {}
  });
  child.stdin.end(input);
}


// Only a settled, user-driven TUI run can receive a follow-up.
const HOOK = __VIBEFACE_HOOK__;

interface PiMessage {
  role: string;
  content?: unknown;
  stopReason?: string;
  errorMessage?: string;
}

interface PiContext {
  mode: string;
  cwd: string;
  sessionManager: {
    getSessionId(): string;
    getLeafId(): string | null;
    getBranch(): readonly { type: string; message?: PiMessage }[];
  };
}

interface Pi {
  on(event: "agent_settled", handler: (event: unknown, ctx: PiContext) => void): void;
  sendUserMessage(text: string, options: { deliverAs: "followUp" }): void;
}

export default function (pi: Pi) {
  if (process.env.VIBEFACE_PI_RUN) return;
  // Pi waits for its handlers. Start the observation and return immediately.
  pi.on("agent_settled", (_event, ctx) => {
    try {
      if (ctx.mode === "tui") report(pi, ctx);
    } catch {}
  });
}

function report(pi: Pi, ctx: PiContext) {
  const session = ctx.sessionManager.getSessionId();
  const turn = ctx.sessionManager.getLeafId();
  const message = ctx.sessionManager.getBranch()
    .findLast((entry) => entry.type === "message")?.message;
  if (message?.role !== "assistant") return;
  const blocks: unknown[] = Array.isArray(message.content) ? message.content : [];
  const text = blocks.filter(isTextBlock).map((block) => block.text).join("\n\n");
  runHook(HOOK, {
    session_id: session,
    turn_id: turn,
    cwd: ctx.cwd,
    stop_reason: message.stopReason,
    error: message.errorMessage,
    last_message: text.slice(0, 8000),
  }, (answer) => {
    if (!answer || typeof answer !== "object" || !("text" in answer)) return;
    const next = answer.text;
    if (typeof next !== "string" || !next.trim()) return;
    if (ctx.sessionManager.getSessionId() !== session || ctx.sessionManager.getLeafId() !== turn) return;
    pi.sendUserMessage(next, { deliverAs: "followUp" });
  });
}

function isTextBlock(block: unknown): block is { type: "text"; text: string } {
  return typeof block === "object" && block !== null
    && "type" in block && block.type === "text"
    && "text" in block && typeof block.text === "string";
}
